def _prepared_bundle_runtime_artifact_payload(
    prepared_bundle_runtime: Mapping[str, Any],
) -> Dict[str, Any]:
    prepared = dict(prepared_bundle_runtime or {})
    records = [
        dict(record)
        for record in list(prepared.get("epoch_execution_queue") or [])
        if isinstance(record, Mapping)
    ]
    detail_jsonl = str(prepared.get("epoch_execution_details_jsonl") or "")
    record_model = str(
        prepared.get("epoch_execution_record_model")
        or "compact_with_detail_jsonl"
    )
    existing_queue_summary = dict(prepared.get("epoch_execution_queue_summary") or {})
    existing_queue_count = int(
        prepared.get("epoch_execution_queue_count")
        or existing_queue_summary.get("epoch_execution_queue_count")
        or 0
    )
    queue_count = len(records) if records else existing_queue_count
    queue_summary = (
        _epoch_execution_queue_artifact_summary(
            records,
            detail_jsonl=detail_jsonl,
            record_model=record_model,
        )
        if records
        else {
            **existing_queue_summary,
            "schema_version": existing_queue_summary.get(
                "schema_version",
                "skyseed-epoch-execution-queue-artifact-summary-v1",
            ),
            "epoch_execution_queue_count": queue_count,
            "epoch_execution_queue_elided": True,
            "record_model": existing_queue_summary.get("record_model", record_model),
            "detail_jsonl": existing_queue_summary.get("detail_jsonl", detail_jsonl),
        }
    )
    prepared_owned_index = dict(prepared.get("prepared_owned_resource_index") or {})
    prepared_scope = dict(prepared.get("prepared_resource_scope_by_slot") or {})
    payload: Dict[str, Any] = {
        "source": prepared.get("source"),
        "physical_sample_count": prepared.get("physical_sample_count"),
        "runtime_transaction_count": prepared.get("runtime_transaction_count"),
        "parameter_update_batch_count": prepared.get("parameter_update_batch_count"),
        "skipped_noop_sample_count": prepared.get("skipped_noop_sample_count"),
        "sample_aligned_event_count": prepared.get("sample_aligned_event_count"),
        "refined_event_count": prepared.get("refined_event_count"),
        "segments": list(prepared.get("segments", [])),
        "replenishment_events": list(prepared.get("replenishment_events", [])),
        "horizon_maintenance_events": list(
            prepared.get("horizon_maintenance_events", [])
        ),
        "replenishment_event_count": _safe_count(
            prepared.get("replenishment_events")
        ),
        "horizon_maintenance_event_count": _safe_count(
            prepared.get("horizon_maintenance_events")
        ),
        "lookahead_preload_queue_count": _safe_count(
            prepared.get("lookahead_preload_queue")
        ),
        "horizon_lifecycle_queue_contract": dict(
            prepared.get("horizon_lifecycle_queue_contract") or {}
        ),
        "sliding_window_contract": dict(
            prepared.get("sliding_window_contract") or {}
        ),
        "prepared_owned_resource_index_summary": {
            "kind": "prepared_owned_resource_index",
            "present": bool(prepared_owned_index),
            "slot_count": int(prepared_owned_index.get("slot_count") or 0),
            "resource_count": int(prepared_owned_index.get("resource_count") or 0),
            "resource_scope_by_slot_elided": True,
        },
        "prepared_resource_scope_by_slot_summary": {
            "kind": "resource_scope_by_slot",
            "present": bool(prepared_scope),
            "slot_count": len(prepared_scope),
            "resource_count": sum(
                len(list(items or [])) for items in prepared_scope.values()
            ),
            "resource_scope_by_slot_elided": True,
        },
        "bpf_generation_slot_allocator": dict(
            prepared.get("bpf_generation_slot_allocator") or {}
        ),
        "pre_runtime_bpf_owned_prepare": (
            _pre_runtime_bpf_owned_prepare_report_summary(
                prepared.get("pre_runtime_bpf_owned_prepare"),
                artifact_path=str(prepared.get("pre_runtime_bpf_owned_prepare_json") or ""),
            )
        ),
        "pre_runtime_bpf_owned_prepare_json": str(
            prepared.get("pre_runtime_bpf_owned_prepare_json") or ""
        ),
        "current_horizon_host_install": (
            _current_horizon_host_install_artifact_summary(
                prepared.get("current_horizon_host_install")
            )
        ),
        "pre_epoch_host_prewarm": _pre_epoch_host_prewarm_artifact_summary(
            prepared.get("pre_epoch_host_prewarm")
        ),
        "run_window_resource_coverage_plan_summary": (
            _collection_artifact_summary(
                prepared.get("run_window_resource_coverage_plan")
            )
            if "run_window_resource_coverage_plan" in prepared
            else {}
        ),
        "epoch_execution_details_jsonl": detail_jsonl,
        "epoch_execution_record_model": record_model,
        "epoch_execution_queue_summary": queue_summary,
        "epoch_execution_queue_count": queue_count,
        "epoch_execution_queue_elided": True,
    }
    return {
        key: value
        for key, value in payload.items()
        if value not in (None, {}, [])
    }


def _prepared_update_bundle_with_continuous_runtime_execution(
    *,
    prepared_update_bundle: Mapping[str, Any],
    runtime_report: Mapping[str, Any],
) -> Dict[str, Any]:
    updated = dict(prepared_update_bundle or {})
    if runtime_report.get("prepared_bundle_runtime") is not None:
        updated["continuous_runtime_execution"] = (
            _prepared_bundle_runtime_artifact_payload(
                dict(runtime_report.get("prepared_bundle_runtime") or {})
            )
        )
    return updated


def _runtime_backend_artifact_fields(
    *,
    records: Sequence[Dict[str, Any]],
    final_runtime_connectivity_validation: Dict[str, Any] | None = None,
) -> Dict[str, Any]:
    final_validation = dict(final_runtime_connectivity_validation or {})
    linux_gz_fallback_command_count = sum(
        int(record.get("linux_gz_fallback_command_count") or 0)
        for record in records
    )
    eligible_core_fallback_to_linux = sum(
        int(record.get("eligible_core_fallback_to_linux") or 0)
        for record in records
    )
    bpf_classifier_miss_count = sum(
        int(record.get("bpf_classifier_miss_count") or 0) for record in records
    ) + int(final_validation.get("bpf_classifier_miss_count") or 0)
    bpf_ping_path_hit_count = sum(
        int(record.get("bpf_ping_path_hit_count") or 0) for record in records
    ) + int(final_validation.get("bpf_ping_path_hit_count") or 0)
    bpf_return_handoff_hit_count = sum(
        int(record.get("bpf_return_handoff_hit_count") or 0) for record in records
    ) + int(final_validation.get("bpf_return_handoff_hit_count") or 0)
    return {
        "linux_gz_fallback_enabled": any(
            bool(record.get("linux_gz_fallback_enabled")) for record in records
        )
        or linux_gz_fallback_command_count > 0
        or eligible_core_fallback_to_linux > 0,
        "linux_gz_fallback_command_count": linux_gz_fallback_command_count,
        "eligible_core_fallback_to_linux": eligible_core_fallback_to_linux,
        "bpf_classifier_miss_count": bpf_classifier_miss_count,
        "bpf_ping_path_hit_count": bpf_ping_path_hit_count,
        "bpf_return_handoff_hit_count": bpf_return_handoff_hit_count,
    }


def _runtime_failure_backend_artifact_fields(
    runtime_report: Dict[str, Any],
) -> Dict[str, Any]:
    def parse_counter(text: str, key: str) -> int:
        marker = f"{key}="
        if marker not in text:
            return 0
        tail = text.split(marker, 1)[1]
        token = tail.split(";", 1)[0].split(",", 1)[0].strip()
        try:
            return int(token)
        except ValueError:
            return 0

    messages: List[str] = []
    outcome = dict(runtime_report.get("outcome") or {})
    if outcome.get("failure_reason"):
        messages.append(str(outcome.get("failure_reason")))
    failure_context = dict(runtime_report.get("failure_context") or {})
    exception = dict(failure_context.get("exception") or {})
    if exception.get("message"):
        messages.append(str(exception.get("message")))
    cause = dict(exception.get("cause") or {})
    if cause.get("message"):
        messages.append(str(cause.get("message")))

    skyseed_details = dict(exception.get("skyseed_details") or {})
    backend_apply_contract = dict(skyseed_details.get("backend_apply_contract") or {})
    packet_diagnostics = dict(
        skyseed_details.get("bpf_owned_packet_path_diagnostics") or {}
    )
    linux_gz_fallback_command_count = int(
        backend_apply_contract.get("linux_gz_fallback_command_count") or 0
    )
    eligible_core_fallback_to_linux = int(
        backend_apply_contract.get("eligible_core_fallback_to_linux") or 0
    )
    bpf_classifier_miss_count = int(
        packet_diagnostics.get("bpf_classifier_miss_count") or 0
    )
    bpf_ping_path_hit_count = int(
        packet_diagnostics.get("bpf_ping_path_hit_count") or 0
    )
    bpf_return_handoff_hit_count = int(
        packet_diagnostics.get("bpf_return_handoff_hit_count") or 0
    )
    bpf_miss_drop_counters = {
        key: int(value or 0)
        for key, value in dict(
            packet_diagnostics.get("miss_drop_counters") or {}
        ).items()
    }
    for message in messages:
        linux_gz_fallback_command_count = max(
            linux_gz_fallback_command_count,
            parse_counter(message, "linux_gz_fallback_command_count"),
        )
        eligible_core_fallback_to_linux = max(
            eligible_core_fallback_to_linux,
            parse_counter(message, "eligible_core_fallback_to_linux"),
        )
    linux_gz_fallback_enabled = bool(
        linux_gz_fallback_command_count > 0
        or eligible_core_fallback_to_linux > 0
        or any("bpf_owned_strict_contract_violation" in message for message in messages)
    )
    return {
        "linux_gz_fallback_enabled": linux_gz_fallback_enabled,
        "linux_gz_fallback_command_count": linux_gz_fallback_command_count,
        "eligible_core_fallback_to_linux": eligible_core_fallback_to_linux,
        "bpf_classifier_miss_count": bpf_classifier_miss_count,
        "bpf_ping_path_hit_count": bpf_ping_path_hit_count,
        "bpf_return_handoff_hit_count": bpf_return_handoff_hit_count,
        "bpf_miss_drop_counters": bpf_miss_drop_counters,
    }


def _runtime_failure_context_summary(runtime_report: Dict[str, Any]) -> Dict[str, Any]:
    outcome = dict(runtime_report.get("outcome") or {})
    failure_context = dict(runtime_report.get("failure_context") or {})
    exception = dict(failure_context.get("exception") or {})
    message = str(outcome.get("failure_reason") or exception.get("message") or "")
    skyseed_details = dict(exception.get("skyseed_details") or {})
    packet_diagnostics = dict(
        skyseed_details.get("bpf_owned_packet_path_diagnostics") or {}
    )
    readiness = _safe_dict(skyseed_details.get("bpf_owned_readiness"))
    real_prepare = _safe_dict(
        _safe_dict(readiness.get("prepare_steps")).get("real_backend_prepare")
    )
    attach_reuse = _safe_dict(real_prepare.get("attach_reuse"))
    map_load = _safe_dict(_safe_dict(real_prepare.get("steps")).get("map_load"))
    loaded_interface_roles = _safe_list(map_load.get("loaded_interface_roles"))
    loaded_role_ifindexes = {
        int(item.get("ifindex") or 0)
        for item in loaded_interface_roles
        if isinstance(item, dict)
    }
    active_interfaces = set(_safe_list(readiness.get("active_materialized_interfaces")))
    future_materialized = set(
        _safe_list(readiness.get("future_materialized_attach_eligible_interfaces"))
    )
    future_capacity_only = set(
        _safe_list(readiness.get("future_non_materialized_capacity_only_interfaces"))
    )
    compile_capacity = set(_safe_list(readiness.get("compile_capacity_interfaces")))
    attached_details_by_interface = {
        str(item.get("interface_ref") or item.get("interface_name") or ""): dict(item)
        for item in _safe_list(readiness.get("attached_interface_details"))
        if isinstance(item, dict)
    }
    classifications_by_interface = {
        str(item.get("interface_ref") or ""): dict(item)
        for item in _safe_list(
            _safe_dict(readiness.get("resident_attach_coverage")).get(
                "interface_classifications"
            )
        )
        if isinstance(item, dict)
    }
    resolved_entries = [
        dict(item)
        for item in _safe_list(readiness.get("resolved_mpls_flow_entries"))
        if isinstance(item, dict)
    ]

    def generated_maps_for_interface(interface_ref: str) -> Dict[str, Any]:
        entries = [
            entry
            for entry in resolved_entries
            if entry.get("ingress_interface") == interface_ref
            or entry.get("out_interface") == interface_ref
        ]
        by_map: Dict[str, int] = {}
        sample_keys: List[Dict[str, Any]] = []
        for entry in entries:
            map_type = str(entry.get("map_type") or "")
            by_map[map_type] = by_map.get(map_type, 0) + 1
            if len(sample_keys) < 8 and map_type in {
                "ingress_classifier_map",
                "core_lfib_map",
                "egress_handoff_map",
            }:
                sample_keys.append(
                    {
                        "map_type": map_type,
                        "generation": entry.get("generation"),
                        "ingress_ifindex": entry.get("ingress_ifindex"),
                        "label": entry.get("label"),
                        "direction": entry.get("direction"),
                    }
                )
        return {
            "generated_entry_count_by_map": dict(sorted(by_map.items())),
            "generated_sample_keys": sample_keys,
        }

    delta_attach_failure: Dict[str, Any] | None = None
    if attach_reuse and (
        str(readiness.get("reason") or "") == "tc_bpf_mpls_delta_attach_failed"
        or int(attach_reuse.get("delta_attach_count") or 0) > 0
    ):
        missing_interfaces = [
            str(item)
            for item in _safe_list(attach_reuse.get("missing_interfaces"))
            or _safe_list(attach_reuse.get("delta_attach_interfaces"))
        ]
        missing_direction_by_interface = {
            str(item.get("interface_ref") or ""): dict(item)
            for item in _safe_list(attach_reuse.get("missing_directions"))
            if isinstance(item, dict)
        }
        interface_details: List[Dict[str, Any]] = []
        for interface_ref in missing_interfaces:
            detail = dict(attached_details_by_interface.get(interface_ref) or {})
            classification = dict(classifications_by_interface.get(interface_ref) or {})
            ifindex = int(detail.get("ifindex") or classification.get("ifindex") or 0)
            map_generation = generated_maps_for_interface(interface_ref)
            interface_details.append(
                {
                    "interface_ref": interface_ref,
                    "netns": detail.get("netns"),
                    "dev": detail.get("container_interface_name")
                    or detail.get("interface_name"),
                    "expected_roles": list(
                        detail.get("expected_roles")
                        or classification.get("expected_roles")
                        or []
                    ),
                    "generation": readiness.get("generation_id"),
                    "slice_id": _safe_dict(readiness.get("runtime_epoch_intent")).get(
                        "slice_id"
                    ),
                    "active_materialized": interface_ref in active_interfaces,
                    "future_materialized_attach_eligible": (
                        interface_ref in future_materialized
                    ),
                    "future_non_materialized_capacity_only": (
                        interface_ref in future_capacity_only
                    ),
                    "compile_capacity": interface_ref in compile_capacity,
                    "attached_at_previous_bootstrap_or_reuse_plan": bool(
                        _safe_dict(attach_reuse.get("previous_attach_plan")).get(
                            interface_ref
                        )
                    ),
                    "loaded_interface_role_map_entry": ifindex
                    in loaded_role_ifindexes,
                    "required_attach_directions": _safe_dict(
                        attach_reuse.get("required_attach_plan")
                    ).get(interface_ref),
                    "previous_attach_directions": _safe_dict(
                        attach_reuse.get("previous_attach_plan")
                    ).get(interface_ref),
                    "missing_directions": missing_direction_by_interface.get(
                        interface_ref, {}
                    ).get("missing_directions", []),
                    "classifier_core_egress_generated_keys": map_generation,
                    "classifier_core_egress_loaded_keys": {
                        "loaded_map_load_available": bool(map_load),
                        "runtime_generation_loaded": bool(
                            readiness.get("runtime_generation_loaded")
                        ),
                    },
                }
            )
        delta_attach_failure = {
            "reason": str(readiness.get("reason") or ""),
            "attach_strategy": str(attach_reuse.get("attach_strategy") or ""),
            "delta_attach_count": int(attach_reuse.get("delta_attach_count") or 0),
            "missing_interfaces": missing_interfaces,
            "interface_details": interface_details,
            "map_ready": bool(readiness.get("map_ready")),
            "runtime_generation_loaded": bool(
                readiness.get("runtime_generation_loaded")
            ),
            "active_generation_set": bool(readiness.get("active_generation_set")),
            "strict_operational_clean_expected_map_only": True,
            "classification_candidates": [
                "RESIDENT_ATTACH_COVERAGE_CONTRACT_STILL_INCOMPLETE",
                "UNEXPECTED_DELTA_ATTACH_PATH_IN_STRICT_OPERATIONAL_CLEAN",
            ],
        }
    blocker = message.split(";", 1)[0].strip() if message else None
    summary = {
        "failure_reason": message or None,
        "classified_blocker": blocker,
        "stage": "runtime_exception" if exception else None,
        "source": "runtime_failure_context" if exception else None,
        "bpf_first_failure_counters": {
            "classifier_hit": int(packet_diagnostics.get("classifier_hit") or 0),
            "label_push": int(packet_diagnostics.get("label_push") or 0),
            "egress_handoff_hit": int(
                packet_diagnostics.get("egress_handoff_hit") or 0
            ),
            "label_pop": int(packet_diagnostics.get("label_pop") or 0),
            "core_lfib_hit": int(packet_diagnostics.get("core_lfib_hit") or 0),
            "label_swap": int(packet_diagnostics.get("label_swap") or 0),
            "bpf_classifier_miss_count": int(
                packet_diagnostics.get("bpf_classifier_miss_count") or 0
            ),
            "miss_drop_counters": {
                key: int(value or 0)
                for key, value in dict(
                    packet_diagnostics.get("miss_drop_counters") or {}
                ).items()
            },
        },
    }
    if delta_attach_failure is not None:
        summary["bpf_delta_attach_failure"] = delta_attach_failure
    return summary


def _finalize_runtime_status_fields(
    runtime_report: Dict[str, Any],
    post_run_preflight_report: Dict[str, Any] | None,
) -> Dict[str, Any]:
    status_fields = _runtime_status_fields_from_report(
        runtime_report,
        post_run_preflight_report,
    )
    runtime_report.update(status_fields)
    outcome = dict(runtime_report.get("outcome") or {})
    outcome.update(status_fields)
    outcome["real_apply_success"] = bool(status_fields["event_timeline_execution_success"])
    outcome["ping_success"] = status_fields["pre_rollback_connectivity_success"]
    outcome["rollback_completed"] = bool(status_fields["rollback_success"])
    runtime_report["outcome"] = outcome
    temporal_audit = dict(runtime_report.get("temporal_audit") or {})
    temporal_audit.update(status_fields)
    runtime_report["temporal_audit"] = temporal_audit
    prepared_bundle_runtime = dict(runtime_report.get("prepared_bundle_runtime") or {})
    for key in ("iterations",):
        runtime_report[key] = [
            {**dict(record), **status_fields}
            for record in list(runtime_report.get(key, []))
        ]
    if "epoch_execution_queue" in prepared_bundle_runtime:
        prepared_bundle_runtime["epoch_execution_queue"] = [
            {**dict(record), **status_fields}
            for record in list(prepared_bundle_runtime.get("epoch_execution_queue", []))
        ]
        prepared_bundle_runtime["epoch_execution_queue_count"] = len(
            prepared_bundle_runtime["epoch_execution_queue"]
        )
    elif prepared_bundle_runtime.get("epoch_execution_queue_summary") is not None:
        prepared_bundle_runtime["epoch_execution_queue_count"] = int(
            prepared_bundle_runtime.get("epoch_execution_queue_count")
            or dict(prepared_bundle_runtime.get("epoch_execution_queue_summary") or {}).get(
                "epoch_execution_queue_count"
            )
            or len(list(runtime_report.get("iterations", [])))
        )
        prepared_bundle_runtime["epoch_execution_queue_elided"] = True
    runtime_report["prepared_bundle_runtime"] = prepared_bundle_runtime
    return runtime_report


def _aggregate_node_local_cleanup_reports(
    cleanup_reports: Sequence[Dict[str, Any]],
) -> Dict[str, Any]:
    aggregate: Dict[str, Any] = {
        "requested_command_count": 0,
        "grouped_command_count": 0,
        "duplicate_cleanup_skipped_count": 0,
        "skipped_noop_count": 0,
        "bounded_parallel_worker_count": 0,
        "node_local_rollback_worker_count": 0,
        "node_local_command_batch_count": 0,
        "rollback_attempted_count": 0,
        "rollback_succeeded_count": 0,
        "rollback_failed_count": 0,
    }
    for report in cleanup_reports:
        metrics = dict(report.get("cleanup_metrics") or {})
        for key in (
            "requested_command_count",
            "grouped_command_count",
            "duplicate_cleanup_skipped_count",
            "skipped_noop_count",
            "node_local_command_batch_count",
        ):
            aggregate[key] += int(metrics.get(key, 0) or 0)
        worker_count = int(metrics.get("node_local_rollback_worker_count", 0) or 0)
        aggregate["node_local_rollback_worker_count"] = max(
            aggregate["node_local_rollback_worker_count"],
            worker_count,
        )
        aggregate["bounded_parallel_worker_count"] = max(
            aggregate["bounded_parallel_worker_count"],
            int(metrics.get("bounded_parallel_worker_count", worker_count) or 0),
        )
        rollback_results = list(report.get("rollback_results") or [])
        aggregate["rollback_attempted_count"] += int(
            metrics.get("grouped_command_count", 0) or 0
        )
        aggregate["rollback_succeeded_count"] += sum(
            int(result.get("command_count", 0) or 0)
            for result in rollback_results
            if bool(result.get("success"))
        )
        aggregate["rollback_failed_count"] += sum(
            int(result.get("command_count", 0) or 0)
            for result in rollback_results
            if not bool(result.get("success"))
        )
    return aggregate


def _selected_access_prewarm_resource_scope_by_slot(
    *,
    snapshot_preview_path: Path,
    selected_slice_ids: Sequence[str],
) -> Dict[str, List[str]]:
    if not snapshot_preview_path.exists():
        return {}
    payload = json.loads(snapshot_preview_path.read_text(encoding="utf-8"))
    snapshots = list(payload.get("snapshots", []))
    if not snapshots:
        return {}
    selected = {str(slice_id) for slice_id in selected_slice_ids if str(slice_id)}
    scope_by_slot: Dict[str, set[str]] = {}
    for snapshot in snapshots:
        time_slice = dict(snapshot.get("time_slice", {}))
        slice_id = str(time_slice.get("slice_id", ""))
        if slice_id not in selected:
            continue
        for link in list(snapshot.get("active_links", [])):
            slot_type = str(link.get("slot_type"))
            if slot_type not in {"ut_access", "gw_access"}:
                continue
            slot_name = str(link.get("link_id"))
            binding = dict(link.get("binding", {}) or {})
            if not slot_name or not binding:
                continue
            scope_by_slot.setdefault(slot_name, set()).add(
                dynamic_slot_binding_resource_key(slot_type, binding)
            )
    return {
        slot_name: sorted(resource_keys)
        for slot_name, resource_keys in sorted(scope_by_slot.items())
        if resource_keys
    }


def _prewarm_selected_slice_ids_for_horizon(
    *,
    segment_queue: Sequence[Mapping[str, Any]],
    lookahead_preload_queue: Sequence[Mapping[str, Any]],
) -> List[str]:
    selected = {
        str(entry.get("slice_id"))
        for entry in list(segment_queue) + list(lookahead_preload_queue)
        if str(entry.get("slice_id"))
    }
    return sorted(selected)


def _run_window_resource_coverage_plan(
    *,
    snapshot_preview_path: Path,
    segment_queue: Sequence[Mapping[str, Any]],
    lookahead_preload_queue: Sequence[Mapping[str, Any]],
    prepared_resource_scope_by_slot: Mapping[str, Sequence[str] | set[str]],
    topology: Mapping[str, Any],
) -> Dict[str, Any]:
    selected_slice_ids = _prewarm_selected_slice_ids_for_horizon(
        segment_queue=segment_queue,
        lookahead_preload_queue=lookahead_preload_queue,
    )
    required_access_scope = _selected_access_prewarm_resource_scope_by_slot(
        snapshot_preview_path=snapshot_preview_path,
        selected_slice_ids=selected_slice_ids,
    )
    required_static_scope = _static_inventory_materialization_resource_scope_by_slot(
        topology=dict(topology),
        slot_types=("same_plane_isl", "cross_plane_isl"),
    )
    required_scope = _merge_resource_scope_by_slot(
        required_access_scope,
        required_static_scope,
    )
    prepared_scope = {
        str(slot_name): {
            str(resource_key)
            for resource_key in list(resource_keys or [])
            if str(resource_key)
        }
        for slot_name, resource_keys in dict(prepared_resource_scope_by_slot or {}).items()
        if str(slot_name)
    }
    unresolved: List[Dict[str, str]] = []
    for slot_name, required_keys in sorted(required_scope.items()):
        prepared_keys = prepared_scope.get(str(slot_name), set())
        for resource_key in list(required_keys or []):
            if str(resource_key) not in prepared_keys:
                unresolved.append(
                    {
                        "slot_name": str(slot_name),
                        "resource_key": str(resource_key),
                    }
                )
    planned_runtime_horizons = [
        dict(entry)
        for entry in segment_queue
        if str(entry.get("classification") or "") == "runtime_epoch"
    ]
    return {
        "schema_version": "skyseed-run-window-resource-coverage-plan-v1",
        "contract": "run_window_bounded_resource_preparation",
        "resource_preparation_stage": "startup/prewarm",
        "runtime_or_lookahead_resource_creation_allowed": False,
        "planned_run_horizon_count": len(planned_runtime_horizons),
        "lookahead_horizon_count": len(list(lookahead_preload_queue or [])),
        "resource_coverage_window": {
            "slice_ids": selected_slice_ids,
            "current_execution_event_count": len(list(segment_queue or [])),
            "lookahead_preload_event_count": len(list(lookahead_preload_queue or [])),
        },
        "required_access_resource_count": sum(
            len(keys) for keys in required_access_scope.values()
        ),
        "required_static_inventory_resource_count": sum(
            len(keys) for keys in required_static_scope.values()
        ),
        "required_resource_union_count": sum(
            len(keys) for keys in required_scope.values()
        ),
        "materialized_resource_count": sum(
            len(keys) for keys in prepared_scope.values()
        ),
        "unresolved_count": len(unresolved),
        "newly_required_but_not_prematerialized_count": len(unresolved),
        "unresolved_resources": unresolved[:50],
        "required_resource_scope_by_slot": required_scope,
        "prepared_resource_scope_by_slot": {
            slot_name: sorted(resource_keys)
            for slot_name, resource_keys in sorted(prepared_scope.items())
        },
        "static_inventory_slot_types": ["same_plane_isl", "cross_plane_isl"],
    }


def _runtime_exception_details(exc: BaseException) -> Dict[str, Any]:
    details: Dict[str, Any] = {
        "exception_type": type(exc).__name__,
        "message": str(exc),
        "traceback": traceback.format_exception(type(exc), exc, exc.__traceback__),
    }
    skyseed_details = getattr(exc, "skyseed_details", None)
    if isinstance(skyseed_details, dict):
        details["skyseed_details"] = _json_safe(skyseed_details)
    cause = getattr(exc, "__cause__", None)
    if cause is not None:
        details["cause"] = _runtime_exception_details(cause)
    if isinstance(exc, NodeLocalBatchFailure):
        result = exc.result
        details["node_local_batch_failure"] = {
            "node_id": result.node_id,
            "phase": result.phase,
            "returncode": result.returncode,
            "command_count": result.command_count,
            "descriptions": list(result.descriptions),
            "stdout": _trim_text(result.stdout),
            "stderr": _trim_text(result.stderr),
            "wall_seconds": round(float(result.wall_seconds), 6),
        }
    elif isinstance(exc, RuntimeCommandFailure):
        result = exc.result
        details["runtime_command_failure"] = {
            "node_id": result.node_id,
            "phase": result.phase,
            "description": result.description,
            "command": list(result.command),
            "returncode": result.returncode,
            "stdout": _trim_text(result.stdout),
            "stderr": _trim_text(result.stderr),
        }
    return details


def _frozen_runtime_ping_observation_schedule(
    session: ActiveRuntimeSession,
) -> Tuple[Dict[str, Any], ...]:
    readiness = dict(session.backend.get("bpf_owned_readiness") or {})
    generation = readiness.get("active_generation")
    session_id = str(session.session_id)
    slice_id = session.target_slice.get("slice_id")
    snapshot_token = _canonical_json_hash(
        {
            "session_id": session_id,
            "generation": generation,
            "slice_id": slice_id,
        }
    )[:24]
    requests: List[Dict[str, Any]] = []
    for context in sorted(
        list(getattr(session, "contexts", ()) or ()),
        key=lambda item: (
            str(getattr(item, "ut_id", "")),
            str(getattr(item, "traffic_scope", "")),
            str(getattr(item, "destination_prefix", "")),
            str(getattr(item, "selected_gateway_id", "")),
        ),
    ):
        target_ip = str(getattr(context, "ping_target_ip", "") or "")
        ut_id = str(getattr(context, "ut_id", "") or "")
        if not target_ip or not ut_id:
            continue
        requests.append(
            {
                "snapshot_token": snapshot_token,
                "session_id": session_id,
                "generation": generation,
                "slice_id": slice_id,
                "ut_id": ut_id,
                "traffic_scope": str(getattr(context, "traffic_scope", "") or ""),
                "destination_prefix": str(
                    getattr(context, "destination_prefix", "") or ""
                ),
                "selected_gateway_id": str(
                    getattr(context, "selected_gateway_id", "") or ""
                ),
                "target_ip": target_ip,
                "target_role": "gateway_service_loopback",
                "gateway_selector_label": getattr(
                    context, "gateway_selector_label", None
                ),
                "fec_id": getattr(context, "gateway_class_id", None),
                "serving_satellite_id": getattr(
                    context, "serving_satellite_id", None
                ),
            }
        )
    return tuple(requests)


def _runtime_ping_observation_request_superseded(
    request: Mapping[str, Any],
    current_session: ActiveRuntimeSession | None,
) -> bool:
    if current_session is None:
        return True
    readiness = dict(current_session.backend.get("bpf_owned_readiness") or {})
    current_identity = {
        "session_id": str(current_session.session_id),
        "generation": readiness.get("active_generation"),
        "slice_id": current_session.target_slice.get("slice_id"),
    }
    request_identity = {
        "session_id": str(request.get("session_id") or ""),
        "generation": request.get("generation"),
        "slice_id": request.get("slice_id"),
    }
    return current_identity != request_identity


def _frozen_container_pid_cache_for_maintenance_worker(
    network_executor: Any,
) -> Dict[str, int]:
    snapshot = network_executor.frozen_container_pid_cache_snapshot()
    normalized = {
        str(node_id): int(pid)
        for node_id, pid in dict(snapshot or {}).items()
        if str(node_id) and int(pid) > 0
    }
    if not normalized or len(normalized) != len(dict(snapshot or {})):
        raise RuntimeError("maintenance_worker_frozen_container_pid_cache_invalid")
    return normalized


def _run_live_temporal_runtime(
    *,
    args: argparse.Namespace,
    run_dir: Path,
    topology_path: Path,
    link_state_path: Path,
    initial_segment: Dict[str, Any],
    validation_targets: Sequence[Dict[str, Any]],
    observe_selectors: Sequence[str],
    stream_progress: bool,
    events: List[Dict[str, Any]],
    progress_update: Callable[..., None] | None = None,
    phase_timing: Dict[str, Any] | None = None,
) -> Dict[str, Any]:
    def _progress(
        *,
        phase: str,
        event_type: str | None = None,
        phase_detail: Dict[str, Any] | None = None,
        epoch_context: Dict[str, Any] | None = None,
        runtime_epochs_completed: int | None = None,
        parameter_epochs_completed: int | None = None,
        write_events: bool = True,
    ) -> None:
        if progress_update is None:
            return
        progress_update(
            phase=phase,
            event_type=event_type,
            phase_detail=phase_detail,
            epoch_context=epoch_context,
            runtime_epochs_completed=runtime_epochs_completed,
            parameter_epochs_completed=parameter_epochs_completed,
            write_events=write_events,
        )

    def _write_live_timing_checkpoint(epoch_records: Sequence[Dict[str, Any]]) -> None:
        epoch_record_snapshot = list(epoch_records)
        rows = _timing_rows({"iterations": epoch_record_snapshot})
        runtime_report_payload = _current_runtime_report_payload(finalized=False)
        runtime_report_payload["iterations"] = epoch_record_snapshot
        runtime_report_payload["timing_summary"] = _live_timing_summary(
            epoch_record_snapshot,
            runtime_mode=str(args.runtime_mode),
            forwarding_backend=str(args.forwarding_backend),
        )
        _write_json(
            run_dir / "timing.json",
            {
                "finalized": False,
                "phase_timing": dict(phase_timing or {}),
                "timing_analysis": _timing_analysis(
                    phase_timing=dict(phase_timing or {}),
                    timing_rows=rows,
                ),
                "timing_summary": _live_timing_summary(
                    epoch_record_snapshot,
                    runtime_mode=str(args.runtime_mode),
                    forwarding_backend=str(args.forwarding_backend),
                ),
                "rows": rows,
            },
        )
        _write_timing_csv(run_dir / "timing.csv", rows)
        _write_json(
            run_dir / "real_runtime_report.json",
            runtime_report_payload,
        )
        _write_json(
            run_dir / "temporal_audit.json",
            _current_temporal_audit_payload(finalized=False),
        )

    deferred_checkpoint_errors: List[str] = []
    checkpoint_queue: "queue.Queue[Sequence[Dict[str, Any]] | None]" = queue.Queue()
    checkpoint_stop = threading.Event()
    live_timing_checkpoints_enabled = _should_run_live_timing_checkpoints(args)

    def _checkpoint_worker() -> None:
        while True:
            item = checkpoint_queue.get()
            try:
                if item is None:
                    return
                started = time.perf_counter()
                _write_live_timing_checkpoint(item)
                if phase_timing is not None:
                    phase_timing["last_deferred_live_timing_checkpoint_wall_seconds"] = round(
                        time.perf_counter() - started,
                        6,
                    )
                    phase_timing["deferred_live_timing_checkpoint_count"] = int(
                        phase_timing.get("deferred_live_timing_checkpoint_count", 0)
                    ) + 1
            except Exception as exc:  # noqa: BLE001
                deferred_checkpoint_errors.append(str(exc))
            finally:
                checkpoint_queue.task_done()

    checkpoint_thread = threading.Thread(
        target=_checkpoint_worker,
        name="deferred-live-timing-checkpoint",
        daemon=True,
    )

    def _queue_live_timing_checkpoint(epoch_records: Sequence[Dict[str, Any]]) -> None:
        if not live_timing_checkpoints_enabled:
            if phase_timing is not None:
                phase_timing[
                    "live_timing_checkpoint_deferred_to_run_end_count"
                ] = int(
                    phase_timing.get(
                        "live_timing_checkpoint_deferred_to_run_end_count",
                        0,
                    )
                ) + 1
            return
        checkpoint_queue.put(list(epoch_records))

    def _flush_live_timing_checkpoints() -> None:
        if not live_timing_checkpoints_enabled:
            return
        checkpoint_queue.join()
        if not checkpoint_stop.is_set():
            checkpoint_stop.set()
            checkpoint_queue.put(None)
            checkpoint_thread.join(timeout=30.0)

    real_installer = MinimalRealLinuxMplsInstaller()
    network_executor = MinimalRealNetworkMutationExecutor(
        max_host_workers=_resolved_max_host_workers(args=args)
    )
    initial_event_timeline_summary = dict(initial_segment.get("summary", {}))
    execution_source = str(initial_event_timeline_summary.get("source", "event_timeline"))
    physical_sample_count = int(initial_event_timeline_summary.get("physical_sample_count", 0) or 0)
    planned_runtime_transaction_count = int(
        initial_event_timeline_summary.get(
            "runtime_transaction_count",
            initial_event_timeline_summary.get("runtime_epoch_count", 0),
        )
        or 0
    )
    planned_parameter_update_batch_count = int(
        initial_event_timeline_summary.get(
            "parameter_update_batch_count",
            initial_event_timeline_summary.get("parameter_epoch_count", 0),
        )
        or 0
    )
    skipped_noop_sample_count = int(
        initial_event_timeline_summary.get(
            "skipped_noop_sample_count",
            initial_event_timeline_summary.get("no_op_sample_count", 0),
        )
        or 0
    )
    sample_aligned_event_count = int(
        initial_event_timeline_summary.get(
            "sample_aligned_event_count",
            planned_runtime_transaction_count + planned_parameter_update_batch_count,
        )
        or 0
    )
    refined_event_count = int(initial_event_timeline_summary.get("refined_event_count", 0) or 0)
    horizon_lifecycle_queue_contract = dict(
        initial_segment.get("horizon_lifecycle_queue_contract") or {}
    )
    lookahead_preload_queue: List[Dict[str, Any]] = list(
        initial_segment.get("lookahead_preload_queue")
        or horizon_lifecycle_queue_contract.get("lookahead_preload_queue")
        or []
    )
    bundle_backed_runtime_inputs = (
        str(initial_segment.get("source") or "") == "prepared_update_bundle"
    )
    frozen_host_plan_by_segment_key: Dict[str, Dict[str, Any]] = {
        str(key): dict(value or {})
        for key, value in dict(
            initial_segment.get("host_network_mutation_plan_by_segment_key") or {}
        ).items()
    }
    frozen_host_plan_source_state_chain = [
        dict(record or {})
        for record in list(
            initial_segment.get("host_network_mutation_source_state_chain") or []
        )
    ]
    frozen_bpf_generation_slot_allocator = dict(
        initial_segment.get("bpf_generation_slot_allocator") or {}
    )
    frozen_bpf_generation_slot_assignments = {
        str(key): dict(value or {})
        for key, value in dict(
            frozen_bpf_generation_slot_allocator.get(
                "assignments_by_segment_epoch_key"
            )
            or {}
        ).items()
    }

    def _host_plan_for_segment(
        *,
        segment_key: str,
        snapshot: TopologySnapshot,
        source_state: Mapping[str, Any],
        source_state_id: str,
    ) -> NetworkMutationPlan:
        if bundle_backed_runtime_inputs or _is_operational_clean_bpf_owned_args(args):
            payload = dict(frozen_host_plan_by_segment_key.get(segment_key) or {})
            if not payload:
                raise RuntimeError(
                    "operational_clean_missing_prepared_host_network_mutation_plan:"
                    f"{segment_key}"
                )
            host_plan = _network_mutation_plan_from_payload(payload)
            if _is_operational_clean_bpf_owned_args(args):
                _assert_host_plan_source_state_aligned(
                    segment_key=segment_key,
                    host_plan=host_plan,
                    current_state_id=source_state_id,
                )
                host_plan = _delta_scoped_network_mutation_plan(host_plan)
            return host_plan
        host_plan = build_network_mutation_plan(
            source_state=source_state,
            source_state_id=source_state_id,
            target_snapshot=enrich_snapshot_runtime_parameters(snapshot),
            transition_name=f"{source_state_id}_to_{snapshot.time_slice.get('slice_id')}",
            runtime_parameter_mutation_policy=runtime_parameter_mutation_policy,
        )
        return host_plan
    _progress(
        phase="runtime_initial_readiness",
        event_type="initial_runtime_readiness_started",
        phase_detail={
            "readiness_profile": "operational_clean_bpf_owned_pre_epoch",
            "gateway_count": len(
                dict(
                    next(iter(initial_segment["context_by_slice"].values()))["snapshot"].planner_hints.get(
                        "gateway_ix_catalog",
                        {},
                    )
                )
            )
            if initial_segment["context_by_slice"]
            else 0,
            "timeout_seconds": round(
                float(args.initial_runtime_readiness_timeout_seconds),
                6,
            ),
        },
    )
    initial_gateway_ids = (
        sorted(
            str(gateway_id)
            for gateway_id in dict(
                next(iter(initial_segment["context_by_slice"].values()))["snapshot"].planner_hints.get(
                    "gateway_ix_catalog", {}
                )
            )
        )
        if initial_segment["context_by_slice"]
        else []
    )
    initial_runtime_readiness = _await_initial_runtime_readiness_for_args(
        args=args,
        gateway_ids=initial_gateway_ids,
        validation_targets=list(validation_targets),
    )
    if phase_timing is not None:
        phase_timing["initial_runtime_readiness_wall_seconds"] = round(
            float(initial_runtime_readiness.get("wall_seconds", 0.0)),
            6,
        )
    readiness_subchecks = list(initial_runtime_readiness.get("subchecks", []))
    readiness_subcheck_status = {
        str(check.get("name")): str(check.get("status"))
        for check in readiness_subchecks
        if check.get("name")
    }
    readiness_blocking_subchecks = [
        str(check.get("name"))
        for check in list(initial_runtime_readiness.get("blocking_subchecks", []))
        if check.get("name")
    ]
    _progress(
        phase=(
            "runtime_initial_readiness_completed"
            if initial_runtime_readiness.get("ready") is True
            else "runtime_initial_readiness_failed"
        ),
        event_type="initial_runtime_readiness_completed",
        phase_detail={
            "ready": initial_runtime_readiness.get("ready"),
            "wall_seconds": initial_runtime_readiness.get("wall_seconds"),
            "readiness_profile": initial_runtime_readiness.get("readiness_profile"),
            "reachable_gateways": initial_runtime_readiness.get("reachable_gateway_count"),
            "subcheck_status": readiness_subcheck_status,
            "blocking_subchecks": readiness_blocking_subchecks,
        },
    )
    if initial_runtime_readiness.get("ready") is not True:
        return {
            "finalized": True,
            "mode": "live_continuous_temporal_runtime",
            "initial_runtime_readiness": initial_runtime_readiness,
            "iterations": [],
            "timing_summary": _live_timing_summary(
                [],
                runtime_mode=str(args.runtime_mode),
                forwarding_backend=str(args.forwarding_backend),
            ),
            "final_cleanup": {
                "node_local": None,
                "host_rollbacks": [],
                "all_cleanup_success": True,
            },
            "temporal_audit": {
                "finalized": True,
                "source": execution_source,
                "physical_sample_count": physical_sample_count,
                "runtime_transaction_count": planned_runtime_transaction_count,
                "parameter_update_batch_count": planned_parameter_update_batch_count,
                "executed_runtime_transaction_count": 0,
                "executed_parameter_update_batch_count": 0,
                "skipped_noop_sample_count": skipped_noop_sample_count,
                "sample_aligned_event_count": sample_aligned_event_count,
                "refined_event_count": refined_event_count,
                "bpf_owned_backend_consumes_event_timeline_transactions": (
                    str(args.forwarding_backend) == "bpf_owned"
                    and execution_source == "event_timeline"
                ),
                "qdisc_updates_execute_only_from_parameter_update_batches": True,
                "no_future_active_link_violation": True,
                "no_future_forwarding_state_violation": True,
                "parameter_epoch_without_topology_mutation": True,
                "runtime_epoch_has_expected_mutation_scope": True,
                "rollback_completed": True,
                "queue_exhausted_or_stopped_by_bound": "initial_runtime_readiness_timeout",
                "horizon_replenishment_status": {
                    "mode": "live_continuous",
                    "initial_segment_count": 1,
                    "replenishment_event_count": 0,
                    "status": "not_started",
                },
                "horizon_lifecycle_queue_contract": dict(
                    horizon_lifecycle_queue_contract
                ),
                "sliding_window_contract": dict(
                    initial_segment.get("sliding_window_contract")
                    or horizon_lifecycle_queue_contract.get("sliding_window_contract")
                    or {}
                ),
                "horizon_maintenance_events": [],
                "lookahead_preload_event_count": len(lookahead_preload_queue),
            },
            "prepared_bundle_runtime": {
                "source": execution_source,
                "physical_sample_count": physical_sample_count,
                "runtime_transaction_count": planned_runtime_transaction_count,
                "parameter_update_batch_count": planned_parameter_update_batch_count,
                "skipped_noop_sample_count": skipped_noop_sample_count,
                "sample_aligned_event_count": sample_aligned_event_count,
                "refined_event_count": refined_event_count,
                "segments": [
                    {
                        "segment_id": initial_segment["segment_id"],
                        "start_time_utc": initial_segment.get("start_time_utc"),
                        "end_time_utc": initial_segment.get("end_time_utc"),
                        "summary": dict(initial_segment.get("summary", {})),
                    }
                ],
                "replenishment_events": [],
                "lookahead_preload_queue": list(lookahead_preload_queue),
                "horizon_lifecycle_queue_contract": dict(
                    horizon_lifecycle_queue_contract
                ),
                "sliding_window_contract": dict(
                    initial_segment.get("sliding_window_contract")
                    or horizon_lifecycle_queue_contract.get("sliding_window_contract")
                    or {}
                ),
                "horizon_maintenance_events": [],
            },
            "outcome": {
                "real_apply_success": False,
                "ping_success": False,
                "rollback_completed": True,
                "failure_reason": "initial_runtime_readiness_timeout",
            },
        }

    current_dynamic_state = dynamic_slot_state_from_link_state(load_link_state(link_state_path))
    current_state_id = f"link_state:{link_state_path.name}"
    segment_queue: List[Dict[str, Any]] = list(
        initial_segment.get("current_execution_queue")
        or horizon_lifecycle_queue_contract.get("current_execution_queue")
        or initial_segment["selected_epoch_queue"]
    )
    horizon_execution_plan = dict(initial_segment.get("horizon_execution_plan") or {})
    horizon_plan_entries = [
        dict(item) for item in list(horizon_execution_plan.get("horizons") or [])
    ]

    def _horizon_id_for_queue_entry(entry: Mapping[str, Any]) -> str:
        return _horizon_id_for_queue_entry_from_plan(
            entry,
            horizon_plan_entries=horizon_plan_entries,
            segment_queue=segment_queue,
        )

    def _context_topology_path(context: Mapping[str, Any]) -> Path:
        rendered = str(dict(context).get("topology_path") or "")
        return Path(rendered).resolve() if rendered else topology_path

    def _context_link_state_path(context: Mapping[str, Any]) -> Path:
        rendered = str(dict(context).get("link_state_path") or "")
        return Path(rendered).resolve() if rendered else link_state_path

    current_runtime_horizon_id = (
        _horizon_id_for_queue_entry(segment_queue[0]) if segment_queue else ""
    )
    current_horizon_index = next(
        (
            index
            for index, horizon in enumerate(horizon_plan_entries)
            if str(horizon.get("horizon_id") or "") == current_runtime_horizon_id
        ),
        -1,
    )
    previous_runtime_horizon_id = (
        str(horizon_plan_entries[current_horizon_index - 1].get("horizon_id") or "")
        if current_horizon_index > 0
        else ""
    )
    next_runtime_horizon_id = (
        str(horizon_plan_entries[current_horizon_index + 1].get("horizon_id") or "")
        if 0 <= current_horizon_index < len(horizon_plan_entries) - 1
        else ""
    )

    def _horizon_generation_key(*, horizon_id: str, generation_id: int) -> str:
        return f"{horizon_id}:generation-{int(generation_id)}"

    def _sliding_horizon_buffer(
        *,
        current_records: Sequence[Mapping[str, Any]],
        prepared_generation_entries: Sequence[Mapping[str, Any]],
        prepared_generation_ids: Sequence[int],
        current_source_state_id: str,
    ) -> Dict[str, Any]:
        horizon_generation_keys_by_horizon: Dict[str, List[str]] = {}
        for item_any in prepared_generation_entries:
            item = dict(item_any)
            horizon_id = str(item.get("horizon_id") or "")
            generation_id = int(
                item.get("logical_generation_id")
                if item.get("logical_generation_id") not in (None, "", "None")
                else item.get("generation_id") or 0
            )
            horizon_generation_keys_by_horizon.setdefault(horizon_id, []).append(
                _horizon_generation_key(
                    horizon_id=horizon_id,
                    generation_id=generation_id,
                )
            )
        current_horizon_generation_keys = sorted(
            horizon_generation_keys_by_horizon.get(current_runtime_horizon_id, [])
        )
        next_horizon_generation_keys = sorted(
            horizon_generation_keys_by_horizon.get(next_runtime_horizon_id, [])
        )
        previous_horizon_generation_keys = sorted(
            horizon_generation_keys_by_horizon.get(previous_runtime_horizon_id, [])
        )
        max_generations_per_horizon = max(
            1,
            len(current_horizon_generation_keys),
            len(next_horizon_generation_keys),
            len(previous_horizon_generation_keys),
        )
        generation_slot_width = _bpf_triple_buffer_generation_slot_width(
            max_generations_per_horizon
        )
        slack_generation_slots = generation_slot_width - max_generations_per_horizon
        reserved_generation_slots = (
            3 * generation_slot_width
        )
        return {
            "schema_version": "skyseed-sliding-horizon-generation-buffer-v1",
            "buffer_model": "previous_current_next_triple_buffer",
            "capacity_contract": {
                "generation_capacity_multiplier": 3,
                "capacity_scales_with": "max_generations_per_horizon",
                "capacity_must_not_scale_with": "total_future_runtime_epochs",
                "max_generations_per_horizon": max_generations_per_horizon,
                "slack_generation_slots": slack_generation_slots,
                "reserved_generation_slots": reserved_generation_slots,
                "physical_generation_slot_width": generation_slot_width,
                "capacity_derivation": (
                    "observed_current_previous_next_horizon_generation_counts"
                ),
                "current_horizon_generation_count": len(
                    current_horizon_generation_keys
                ),
                "next_horizon_generation_count": len(next_horizon_generation_keys),
                "previous_horizon_generation_count": len(
                    previous_horizon_generation_keys
                ),
                "physical_generation_slot_width": int(bpf_generation_slot_width),
            },
            "previous": {
                "horizon_id": previous_runtime_horizon_id,
                "generation_records": [],
                "prepared_horizon_generation_keys": (
                    previous_horizon_generation_keys
                ),
                "status": "not_populated_for_current_run",
            },
            "current": {
                "horizon_id": current_runtime_horizon_id,
                "generation_records": [dict(item) for item in current_records],
                "prepared_horizon_generation_keys": (
                    current_horizon_generation_keys
                ),
                "prepared_generation_ids": [
                    int(item) for item in list(prepared_generation_ids)
                ],
                "current_source_state_id": str(current_source_state_id or ""),
            },
            "next": {
                "horizon_id": next_runtime_horizon_id,
                "generation_records": [],
                "prepared_horizon_generation_keys": next_horizon_generation_keys,
                "status": "reserved_for_horizon_prepare_stage",
            },
        }

    def _advance_session_horizon_state(
        session: ActiveRuntimeSession | None,
        *,
        horizon_id: str,
        target_state_id: str,
    ) -> ActiveRuntimeSession | None:
        if session is None:
            return None
        backend = dict(session.backend or {})
        if str(backend.get("forwarding_backend") or "") != "bpf_owned":
            return session
        readiness = dict(backend.get("bpf_owned_readiness") or {})
        if not readiness:
            return session
        generation_id = int(
            readiness.get("active_generation")
            or readiness.get("generation_id")
            or 0
        )
        target_horizon_id = str(
            horizon_id or readiness.get("current_horizon_id") or ""
        )
        existing_horizon_generation_key = str(
            readiness.get("active_horizon_generation_key") or ""
        )
        existing_physical_horizon_generation_key = str(
            readiness.get("active_physical_horizon_generation_key")
            or readiness.get("physical_horizon_generation_key")
            or ""
        )
        horizon_generation_key = (
            existing_physical_horizon_generation_key
            if existing_physical_horizon_generation_key
            and str(readiness.get("current_horizon_id") or "") == target_horizon_id
            else existing_horizon_generation_key
            if existing_horizon_generation_key
            and str(readiness.get("current_horizon_id") or "") == target_horizon_id
            else _horizon_generation_key(
                horizon_id=target_horizon_id,
                generation_id=generation_id,
            )
        )
        readiness.update(
            {
                "current_horizon_id": target_horizon_id,
                "current_source_state_id": str(target_state_id or ""),
                "active_horizon_generation_key": horizon_generation_key,
                "last_applied_horizon_generation_key": horizon_generation_key,
                "active_physical_horizon_generation_key": horizon_generation_key,
                "last_applied_physical_horizon_generation_key": (
                    horizon_generation_key
                ),
            }
        )
        backend["bpf_owned_readiness"] = readiness
        return replace(session, backend=backend)

    def _stage_session_horizon_for_next_apply(
        session: ActiveRuntimeSession | None,
        *,
        horizon_id: str,
        source_state_id: str,
    ) -> ActiveRuntimeSession | None:
        if session is None:
            return None
        backend = dict(session.backend or {})
        if str(backend.get("forwarding_backend") or "") != "bpf_owned":
            return session
        readiness = dict(backend.get("bpf_owned_readiness") or {})
        if not readiness:
            return session
        readiness = _stage_bpf_owned_readiness_for_preloaded_apply(
            readiness,
            target_horizon_id=str(horizon_id or ""),
            source_state_id=str(source_state_id or ""),
        )
        backend["bpf_owned_readiness"] = readiness
        return replace(session, backend=backend)

    def _bpf_generation_entry_allowed(entry: Mapping[str, Any]) -> bool:
        return (
            str(entry.get("classification") or "")
            in {"runtime_epoch", "parameter_epoch"}
            and bool(entry.get("runtime_apply_allowed", True)) is True
        )

    def _horizon_sequence_index(
        horizon_id: str,
        *,
        fallback_index: int,
    ) -> int:
        normalized = str(horizon_id or "")
        for index, horizon in enumerate(horizon_plan_entries):
            if str(horizon.get("horizon_id") or "") == normalized:
                return index
        if normalized == "current-horizon":
            return 0
        if normalized.startswith("replenished-"):
            suffix = normalized.rsplit("-", 1)[-1]
            if suffix.isdigit():
                return int(suffix)
        return max(0, int(fallback_index))

    def _physical_generation_id_for_horizon(
        *,
        horizon_id: str,
        horizon_sequence_index: int,
        logical_generation_id: int,
        slot_width: int,
    ) -> int:
        try:
            return _bpf_triple_buffer_physical_generation_id(
                horizon_sequence_index=horizon_sequence_index,
                local_generation_id=logical_generation_id,
                generation_slot_width=slot_width,
            )
        except RuntimeError as exc:
            raise RuntimeError(
                "bpf_rolling_generation_slot_capacity_exceeded:"
                + json.dumps(
                    {
                        "horizon_id": str(horizon_id),
                        "horizon_sequence_index": int(horizon_sequence_index),
                        "logical_generation_id": int(logical_generation_id),
                        "generation_slot_width": max(1, int(slot_width)),
                    },
                    sort_keys=True,
                )
            ) from exc

    def _runtime_update_plan_with_bpf_physical_generation(
        runtime_update_plan: RuntimeUpdatePlan,
        *,
        horizon_id: str,
        horizon_sequence_index: int,
        logical_generation_id: int,
        physical_generation_id: int,
        generation_slot_width: int,
    ) -> RuntimeUpdatePlan:
        logical_generation_id = int(logical_generation_id)
        physical_generation_id = int(physical_generation_id)
        generation_slot_width = max(1, int(generation_slot_width))
        target_snapshot = {
            **dict(runtime_update_plan.target_snapshot or {}),
            "bpf_logical_generation_id": logical_generation_id,
            "bpf_physical_generation_id": physical_generation_id,
            "bpf_generation_slot_width": generation_slot_width,
            "bpf_generation_buffer_index": int(horizon_sequence_index % 3),
            "bpf_generation_horizon_id": str(horizon_id),
            "bpf_generation_horizon_sequence_index": int(horizon_sequence_index),
            "bpf_horizon_generation_key": _horizon_generation_key(
                horizon_id=str(horizon_id),
                generation_id=logical_generation_id,
            ),
            "bpf_physical_horizon_generation_key": _horizon_generation_key(
                horizon_id=str(horizon_id),
                generation_id=physical_generation_id,
            ),
        }
        planner = {
            **dict(runtime_update_plan.planner or {}),
            "bpf_generation_slot_allocator": {
                "schema_version": "skyseed-bpf-generation-slot-allocation-v1",
                "buffer_model": "previous_current_next_triple_buffer",
                "horizon_id": str(horizon_id),
                "horizon_sequence_index": int(horizon_sequence_index),
                "buffer_index": int(horizon_sequence_index % 3),
                "logical_generation_id": logical_generation_id,
                "physical_generation_id": physical_generation_id,
                "generation_slot_width": generation_slot_width,
                "horizon_generation_key": _horizon_generation_key(
                    horizon_id=str(horizon_id),
                    generation_id=logical_generation_id,
                ),
                "physical_horizon_generation_key": _horizon_generation_key(
                    horizon_id=str(horizon_id),
                    generation_id=physical_generation_id,
                ),
            },
        }
        return replace(
            runtime_update_plan,
            target_snapshot=target_snapshot,
            planner=planner,
        )

    def _bpf_generation_count_for_entries(
        entries: Sequence[Mapping[str, Any]],
        contexts_by_key: Mapping[str, Mapping[str, Any]],
    ) -> int:
        event_count_by_horizon: Dict[str, int] = {}
        for entry_any in entries:
            entry = dict(entry_any)
            if not _bpf_generation_entry_allowed(entry):
                continue
            segment_key = str(entry.get("segment_epoch_key") or "")
            context = contexts_by_key.get(segment_key)
            if not context:
                continue
            proof = _derive_bpf_owned_readiness_proof(
                runtime_update_plan=dict(context)["runtime_update_plan"],
            )
            if proof.get("logical_intent_ready") is not True:
                continue
            horizon_id = _horizon_id_for_queue_entry(entry)
            event_count_by_horizon[horizon_id] = (
                event_count_by_horizon.get(horizon_id, 0) + 1
            )
        return max(event_count_by_horizon.values(), default=1)

    def _bpf_generation_slot_width_for_entries(
        entries: Sequence[Mapping[str, Any]],
        contexts_by_key: Mapping[str, Mapping[str, Any]],
    ) -> int:
        return _bpf_triple_buffer_generation_slot_width(
            _bpf_generation_count_for_entries(entries, contexts_by_key)
        )

    def _assign_bpf_physical_generation_plans(
        *,
        entries: Sequence[Mapping[str, Any]],
        contexts_by_key: Dict[str, Dict[str, Any]],
        generation_slot_width: int,
        fallback_horizon_sequence_index: int,
    ) -> Dict[str, Dict[str, Any]]:
        assignments: Dict[str, Dict[str, Any]] = {}
        local_generation_index_by_horizon: Dict[str, int] = {}
        for entry_any in entries:
            entry = dict(entry_any)
            if not _bpf_generation_entry_allowed(entry):
                continue
            segment_key = str(entry.get("segment_epoch_key") or "")
            context = dict(contexts_by_key.get(segment_key) or {})
            if not context:
                continue
            runtime_update_plan = context["runtime_update_plan"]
            existing_snapshot = dict(runtime_update_plan.target_snapshot or {})
            existing_physical = existing_snapshot.get("bpf_physical_generation_id")
            proof = _derive_bpf_owned_readiness_proof(
                runtime_update_plan=runtime_update_plan,
            )
            if proof.get("logical_intent_ready") is not True:
                continue
            horizon_id = _horizon_id_for_queue_entry(entry)
            logical_generation_id = int(
                local_generation_index_by_horizon.get(horizon_id, 0)
            )
            local_generation_index_by_horizon[horizon_id] = logical_generation_id + 1
            horizon_sequence_index = _horizon_sequence_index(
                horizon_id,
                fallback_index=fallback_horizon_sequence_index,
            )
            physical_generation_id = (
                int(existing_physical)
                if existing_physical not in (None, "", "None")
                else _physical_generation_id_for_horizon(
                    horizon_id=horizon_id,
                    horizon_sequence_index=horizon_sequence_index,
                    logical_generation_id=logical_generation_id,
                    slot_width=generation_slot_width,
                )
            )
            patched_plan = _runtime_update_plan_with_bpf_physical_generation(
                runtime_update_plan,
                horizon_id=horizon_id,
                horizon_sequence_index=horizon_sequence_index,
                logical_generation_id=logical_generation_id,
                physical_generation_id=physical_generation_id,
                generation_slot_width=generation_slot_width,
            )
            context["runtime_update_plan"] = patched_plan
            contexts_by_key[segment_key] = context
            assignments[segment_key] = {
                "schema_version": "skyseed-bpf-generation-slot-assignment-v1",
                "segment_epoch_key": segment_key,
                "horizon_id": horizon_id,
                "horizon_sequence_index": horizon_sequence_index,
                "buffer_index": horizon_sequence_index % 3,
                "logical_generation_id": logical_generation_id,
                "physical_generation_id": physical_generation_id,
                "generation_id": physical_generation_id,
                "generation_slot_width": max(1, int(generation_slot_width)),
                "horizon_generation_key": _horizon_generation_key(
                    horizon_id=horizon_id,
                    generation_id=logical_generation_id,
                ),
                "physical_horizon_generation_key": _horizon_generation_key(
                    horizon_id=horizon_id,
                    generation_id=physical_generation_id,
                ),
            }
        return assignments

